using System;using System.IO;class Mock {static int Main(){string dir=Path.Combine(Environment.GetEnvironmentVariable("LOCALAPPDATA"),"CampusNetworkSwitch");string me=Path.GetFileName(Environment.GetCommandLineArgs()[0]);if(me.IndexOf("MockPhone",StringComparison.OrdinalIgnoreCase)>=0){File.WriteAllText(Path.Combine(dir,"fallback.txt"),"shown");return 0;}string file=Path.Combine(dir,"count.txt");int n=File.Exists(file)?Int32.Parse(File.ReadAllText(file)):0;n++;File.WriteAllText(file,n.ToString());string[] codes=File.ReadAllText(Path.Combine(dir,"codes.txt")).Split(',');return Int32.Parse(codes[Math.Min(n-1,codes.Length-1)]);}}